<script setup>definePageMeta({middleware:'auth'});const {data,refresh}=await useFetch('/api/cards');const colors={new:'status-red',reading:'status-yellow',done:'status-green'};</script><template><main class="p-7 max-w-7xl mx-auto"><div class="flex justify-between items-end mb-7"><div><h1 class="text-3xl font-black">Papan Informasi</h1><p class="text-slate-600">Merah: baru · Kuning: perlu pemahaman · Hijau: selesai</p></div><button class="btn bg-white" @click="refresh">Muat ulang</button></div><div class="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-7"><NuxtLink v-for="(c,i) in data?.cards" :key="c.id" :to="`/cards/${c.id}`" class="card-board bg-white rounded-2xl overflow-hidden" :class="colors[c.status]" :style="`--tilt:${i%2?1:-1}deg`"><div class="h-36 bg-slate-900 text-white p-5 flex items-end"><h2 class="text-xl font-black">{{c.title}}</h2></div><div class="p-5"><div class="flex justify-between text-sm"><span class="capitalize">{{c.status}}</span><span>{{c.done_count}} / {{c.target_count}}</span></div><div class="h-2 bg-slate-200 rounded mt-3"><div class="h-2 bg-blue-600 rounded" :style="`width:${c.progress}%`"></div></div><p class="text-right text-sm mt-1">{{c.progress}}%</p></div></NuxtLink></div></main></template>